public class StrBuilder_appendFixedWidthPadRight_TriageGen1Test {

    private StrBuilder strBuilder;

    @Before
    public void setUp() {
        strBuilder = new StrBuilder();
    }





    @Test
    public void testAppendFixedWidthPadRight_ObjIsNull_WithDefaultNullText() {
        // Default null text is usually "null" in Commons Lang
        String nullText = strBuilder.getNullText();
        strBuilder.appendFixedWidthPadRight(null, 10, '.');
        String expected = nullText + ".......";
        assertEquals(expected, strBuilder.toString());
    }














}

