public class StrBuilder_appendFixedWidthPadRight_TriageGen1Test {

    private StrBuilder strBuilder;

    @Before
    public void setUp() {
        strBuilder = new StrBuilder();
    }













    @Test
    public void testAppendFixedWidthPadRight_StrLenGreaterThanWidth() {
        // The implementation uses str.getChars(0, width, buffer, size) 
        // which effectively truncates the string to the width
        strBuilder.appendFixedWidthPadRight("abcdef", 3, '*');
        assertEquals("abc", strBuilder.toString());
    }






}

